"""


def solution():
    # Write your code in Python.
    import sys

    n = int(sys.stdin.readline().rstrip('\n'))

    for i in range(n):
        s = sys.stdin.readline().rstrip('\n')
        s = s.split()

        if s[0] == "দেওয়া":
            if len(s) == 2:
                print(s[1])
            else:
                print("No")
        elif s[0] == "বর্ণনা করা":
            if len(s) == 2:
                print(s[1])
            else:
                print("No")
        elif s[0] == "ইনপুট দেওয়া":
            if len(s) == 2:
                print(s[1])
            else:
                print("No")
        else:
            print("No")


if __name__ == "__main__":
    solution()

