```python
#!/usr/bin/python

import sys

def main():
    input_line = sys.stdin.readline()
    if input_line == '':
        print("End of file")
        return

    line = input_line.split()
    if line[0] == 'Garuda':
        print('Garuda')
    elif line[0] == 'Human':
        print('Human')
    elif line[0] == 'GarudaHuman':
        print('GarudaHuman')
    else:
        print('Wrong')

if __name__ == '__main__':
    main()
```

